                "timestamp": datetime.datetime.now().isoformat(timespec="seconds"),
                "program": os.path.abspath(a.classify),
                "program_bytes": size,
                "comment_report": crep,
                "n_images": n,
                "n_scored": n,
                "excluded": excluded,
                "accuracy": acc,
                "per_class_accuracy": per_class,
                "classes": CLASSES,
                "confusion": conf,
