                "n_errors": n_err,
                "n_timeouts": n_to,
                "mean_ms": mean_ms,
                "timeout_s": a.timeout,
                "wall_s": wall,
            }, f, indent=2)
    if a.preds:
        with open(a.preds, "w", newline="") as f:
            w = csv.writer(f)
            w.writerow(["path", "true", "pred", "ms", "error"])
            for p, t, pr, ms, er in rows:
                w.writerow([p, t, pr, f"{ms:.1f}", er])
    return 0


